<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores: A Historical Trend Analysis (1934–2026)</title>
<style>
  :root {
    --gold: #C9A227;
    --gold-light: #F0D080;
    --dark: #1A1A2E;
    --darker: #0F0F1A;
    --card-bg: #16213E;
    --card-border: #0F3460;
    --text: #E0E0E0;
    --text-muted: #9A9AB0;
    --accent: #E94560;
    --accent2: #533483;
    --green: #4CAF50;
    --teal: #26A69A;
    --font-sans: 'Georgia', 'Times New Roman', serif;
    --font-mono: 'Courier New', monospace;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--darker);
    color: var(--text);
    font-family: var(--font-sans);
    line-height: 1.7;
    font-size: 16px;
  }

  /* ── HEADER ── */
  header {
    background: linear-gradient(135deg, var(--darker) 0%, #1a0a30 50%, var(--darker) 100%);
    border-bottom: 2px solid var(--gold);
    padding: 60px 40px 50px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  header::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 50% 0%, rgba(201,162,39,0.15) 0%, transparent 65%);
  }
  .oscar-icon {
    font-size: 3rem;
    display: block;
    margin-bottom: 12px;
    filter: drop-shadow(0 0 20px rgba(201,162,39,0.6));
  }
  header h1 {
    font-size: clamp(1.6rem, 4vw, 2.8rem);
    color: var(--gold);
    letter-spacing: 0.02em;
    text-shadow: 0 2px 20px rgba(201,162,39,0.4);
    position: relative;
    z-index: 1;
    line-height: 1.3;
  }
  header .subtitle {
    color: var(--text-muted);
    font-size: 1rem;
    margin-top: 12px;
    position: relative;
    z-index: 1;
    font-style: italic;
  }
  .report-meta {
    margin-top: 20px;
    display: flex;
    justify-content: center;
    gap: 24px;
    flex-wrap: wrap;
    position: relative;
    z-index: 1;
  }
  .report-meta span {
    background: rgba(201,162,39,0.1);
    border: 1px solid rgba(201,162,39,0.3);
    color: var(--gold-light);
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 0.85rem;
    font-family: var(--font-mono);
  }

  /* ── LAYOUT ── */
  main { max-width: 1100px; margin: 0 auto; padding: 40px 24px 80px; }

  /* ── NAV ── */
  nav {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 20px 28px;
    margin-bottom: 48px;
  }
  nav h3 { color: var(--gold); font-size: 0.85rem; letter-spacing: 0.12em; text-transform: uppercase; margin-bottom: 14px; }
  nav ol { padding-left: 20px; }
  nav ol li { margin-bottom: 6px; }
  nav ol li a { color: var(--text-muted); text-decoration: none; font-size: 0.95rem; transition: color 0.2s; }
  nav ol li a:hover { color: var(--gold); }

  /* ── SECTIONS ── */
  section { margin-bottom: 64px; scroll-margin-top: 24px; }
  section h2 {
    font-size: 1.6rem;
    color: var(--gold);
    border-bottom: 1px solid rgba(201,162,39,0.3);
    padding-bottom: 12px;
    margin-bottom: 28px;
    display: flex;
    align-items: center;
    gap: 12px;
  }
  section h2 .sec-num {
    background: var(--gold);
    color: var(--darker);
    font-size: 0.8rem;
    font-weight: bold;
    padding: 2px 8px;
    border-radius: 4px;
    font-family: var(--font-mono);
  }
  section h3 { font-size: 1.15rem; color: var(--gold-light); margin: 28px 0 12px; }
  section p { margin-bottom: 16px; color: var(--text); }

  /* ── KPI CARDS ── */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 20px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: linear-gradient(135deg, var(--card-bg) 0%, #1f2f55 100%);
    border: 1px solid var(--card-border);
    border-top: 3px solid var(--gold);
    border-radius: 10px;
    padding: 24px 20px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, rgba(201,162,39,0.3), transparent);
  }
  .kpi-value {
    font-size: 2.8rem;
    font-weight: bold;
    color: var(--gold);
    line-height: 1;
    text-shadow: 0 0 20px rgba(201,162,39,0.3);
    margin-bottom: 8px;
    font-family: var(--font-mono);
  }
  .kpi-label { font-size: 0.85rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; }
  .kpi-sub { font-size: 0.8rem; color: var(--text-muted); margin-top: 6px; font-style: italic; }

  /* ── PROSE CALLOUT ── */
  .callout {
    background: rgba(201,162,39,0.07);
    border-left: 4px solid var(--gold);
    border-radius: 0 8px 8px 0;
    padding: 16px 22px;
    margin: 24px 0;
    font-style: italic;
    color: var(--text-muted);
  }

  /* ── TABLE ── */
  .table-wrap { overflow-x: auto; margin: 20px 0; }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
  }
  thead th {
    background: rgba(201,162,39,0.15);
    color: var(--gold);
    padding: 10px 14px;
    text-align: left;
    font-size: 0.8rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 2px solid rgba(201,162,39,0.4);
  }
  tbody tr { border-bottom: 1px solid rgba(255,255,255,0.05); transition: background 0.15s; }
  tbody tr:hover { background: rgba(255,255,255,0.04); }
  tbody td { padding: 9px 14px; color: var(--text); }
  .rank-badge {
    background: var(--gold);
    color: var(--darker);
    font-size: 0.75rem;
    font-weight: bold;
    padding: 2px 7px;
    border-radius: 4px;
    font-family: var(--font-mono);
  }
  .win-bar-cell { min-width: 160px; }
  .win-bar-bg { background: rgba(255,255,255,0.07); border-radius: 4px; height: 10px; }
  .win-bar-fill { background: linear-gradient(90deg, var(--gold), var(--gold-light)); border-radius: 4px; height: 10px; transition: width 0.3s; }

  /* ── SVG CHARTS ── */
  .chart-container {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 28px;
    margin: 24px 0;
  }
  .chart-title {
    font-size: 0.9rem;
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 20px;
    text-align: center;
  }
  svg text { font-family: 'Georgia', serif; }

  /* ── ERA CARDS ── */
  .era-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; margin: 24px 0; }
  .era-card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 22px 18px;
    position: relative;
  }
  .era-card .era-badge {
    position: absolute;
    top: -1px; right: 16px;
    background: var(--gold);
    color: var(--darker);
    font-size: 0.7rem;
    font-weight: bold;
    padding: 3px 10px;
    border-radius: 0 0 6px 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }
  .era-card h4 { color: var(--gold-light); font-size: 1.05rem; margin-bottom: 4px; }
  .era-card .era-years { color: var(--text-muted); font-size: 0.8rem; margin-bottom: 14px; }
  .era-card .era-stat { display: flex; justify-content: space-between; font-size: 0.85rem; margin-bottom: 6px; }
  .era-card .era-stat span:first-child { color: var(--text-muted); }
  .era-card .era-stat span:last-child { color: var(--text); font-weight: bold; }
  .era-composers { margin-top: 12px; }
  .era-composers .ec-title { font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
  .composer-chip {
    display: inline-block;
    background: rgba(201,162,39,0.12);
    border: 1px solid rgba(201,162,39,0.25);
    color: var(--gold-light);
    font-size: 0.78rem;
    padding: 2px 10px;
    border-radius: 20px;
    margin: 2px 3px 2px 0;
  }

  /* ── MILESTONE TIMELINE ── */
  .timeline { position: relative; padding-left: 28px; margin: 24px 0; }
  .timeline::before {
    content: '';
    position: absolute;
    left: 9px; top: 0; bottom: 0;
    width: 2px;
    background: linear-gradient(to bottom, var(--gold), transparent);
  }
  .tl-item { position: relative; margin-bottom: 28px; }
  .tl-dot {
    position: absolute;
    left: -22px; top: 4px;
    width: 10px; height: 10px;
    border-radius: 50%;
    background: var(--gold);
    box-shadow: 0 0 10px rgba(201,162,39,0.5);
  }
  .tl-year { font-size: 0.8rem; color: var(--gold); font-family: var(--font-mono); font-weight: bold; }
  .tl-title { font-size: 1rem; color: var(--text); margin: 2px 0; }
  .tl-desc { font-size: 0.88rem; color: var(--text-muted); }

  /* ── TAKEAWAYS ── */
  .takeaway-list { list-style: none; }
  .takeaway-list li {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-left: 4px solid var(--gold);
    border-radius: 0 8px 8px 0;
    padding: 16px 20px;
    margin-bottom: 14px;
    display: flex;
    gap: 14px;
    align-items: flex-start;
  }
  .takeaway-list .tk-num {
    background: var(--gold);
    color: var(--darker);
    font-weight: bold;
    font-size: 0.85rem;
    padding: 2px 9px;
    border-radius: 4px;
    flex-shrink: 0;
    margin-top: 2px;
    font-family: var(--font-mono);
  }
  .takeaway-list .tk-text { color: var(--text); font-size: 0.95rem; }
  .takeaway-list .tk-text strong { color: var(--gold-light); }

  /* ── FULL DATA TABLE ── */
  .data-table-wrap { max-height: 420px; overflow-y: auto; border-radius: 8px; border: 1px solid var(--card-border); }
  .data-table-wrap::-webkit-scrollbar { width: 6px; }
  .data-table-wrap::-webkit-scrollbar-track { background: var(--darker); }
  .data-table-wrap::-webkit-scrollbar-thumb { background: rgba(201,162,39,0.4); border-radius: 3px; }
  .sticky-head thead th { position: sticky; top: 0; z-index: 2; }

  /* ── FOOTER ── */
  footer {
    background: var(--card-bg);
    border-top: 1px solid var(--card-border);
    text-align: center;
    padding: 32px 24px;
    color: var(--text-muted);
    font-size: 0.85rem;
  }
  footer a { color: var(--gold); text-decoration: none; }
</style>
